-- PASO 0 - PREFLIGHT (22 comprobaciones, solo lectura): estado previo a la instalacion
-- Base de datos: u611730801_Plataforma (referencias explicitas; NO depende de USE ni de la base seleccionada en phpMyAdmin).
-- VERIFICACION DE SOLO LECTURA: no modifica nada. Cada fila debe decir OK (o ser informativa). Cualquier DETENER: no continuar.
-- Deben quedar solo OK e informativas. Ejecutelo de nuevo justo antes de la etapa 1.
--

SET SESSION group_concat_max_len = 1048576;
SELECT 'group_concat_max_len suficiente (>= 1048576) en esta sesion' AS verificacion, IF(@@SESSION.group_concat_max_len >= 1048576, 'OK', 'DETENER') AS resultado;
SELECT 'version 11.8.9' AS verificacion, IF(VERSION() LIKE '11.8.9-MariaDB%', 'OK', 'DETENER') AS resultado;
SELECT 'canecas_ventas, canecas_productos y empresas existen' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME IN ('canecas_ventas','canecas_productos','empresas'))=3, 'OK', 'DETENER') AS resultado;
SELECT 'canecas_secuencias no existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_secuencias')=0, 'OK', 'DETENER') AS resultado;
SELECT 'direccion_entrega no existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas' AND COLUMN_NAME='direccion_entrega')=0, 'OK', 'DETENER') AS resultado;
SELECT 'chk_can_venta_direccion no existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas' AND CONSTRAINT_NAME='chk_can_venta_direccion')=0, 'OK', 'DETENER') AS resultado;
SELECT 'ref_auto y doc_auto no existen' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND ((TABLE_NAME='canecas_compras' AND COLUMN_NAME='ref_auto') OR (TABLE_NAME='canecas_ventas' AND COLUMN_NAME='doc_auto')))=0, 'OK', 'DETENER') AS resultado;
SELECT 'activo_unico no existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos' AND COLUMN_NAME='activo_unico')=0, 'OK', 'DETENER') AS resultado;
SELECT 'uq_can_producto_activo_unico no existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos' AND INDEX_NAME='uq_can_producto_activo_unico')=0, 'OK', 'DETENER') AS resultado;
SELECT 'triggers de ventas anteriores presentes' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME IN ('trg_can_venta_bu','trg_can_venta_bd'))=2, 'OK', 'DETENER') AS resultado;
SELECT 'trigger de actualizacion aun sin direccion_entrega' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND ACTION_STATEMENT LIKE '%direccion_entrega%')=0, 'OK', 'DETENER') AS resultado;
SELECT 'ninguna empresa con mas de una caneca activa' AS verificacion, IF((SELECT COUNT(*) FROM (SELECT empresa_id FROM `u611730801_Plataforma`.canecas_productos WHERE activo=1 GROUP BY empresa_id HAVING COUNT(*)>1) t)=0, 'OK', 'DETENER') AS resultado;
SELECT 'sin sufijos COMP de mas de 15 digitos en canecas_compras.referencia' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_compras WHERE UPPER(TRIM(referencia)) REGEXP '^COMP[ _-]?[0-9]{16,}$')=0, 'OK', 'DETENER') AS resultado;
SELECT 'sin sufijos VTA de mas de 15 digitos en canecas_ventas.documento' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_ventas WHERE UPPER(TRIM(documento)) REGEXP '^VTA[ _-]?[0-9]{16,}$')=0, 'OK', 'DETENER') AS resultado;
SELECT 'sin sufijos CAN de mas de 15 digitos en canecas_productos.codigo' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_productos WHERE UPPER(TRIM(codigo)) REGEXP '^CAN[ _-]?[0-9]{16,}$')=0, 'OK', 'DETENER') AS resultado;
SELECT 'maximo historico COMP por empresa (empresa:valor)' AS verificacion, COALESCE(GROUP_CONCAT(CONCAT(empresa_id, ':', maximo) ORDER BY empresa_id SEPARATOR ', '), 'ninguno') AS resultado FROM (SELECT empresa_id, MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(referencia)), '^COMP[ _-]?', '') AS UNSIGNED)) AS maximo FROM `u611730801_Plataforma`.canecas_compras WHERE UPPER(TRIM(referencia)) REGEXP '^COMP[ _-]?[0-9]{1,15}$' GROUP BY empresa_id) h;
SELECT 'maximo historico VTA por empresa (empresa:valor)' AS verificacion, COALESCE(GROUP_CONCAT(CONCAT(empresa_id, ':', maximo) ORDER BY empresa_id SEPARATOR ', '), 'ninguno') AS resultado FROM (SELECT empresa_id, MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(documento)), '^VTA[ _-]?', '') AS UNSIGNED)) AS maximo FROM `u611730801_Plataforma`.canecas_ventas WHERE UPPER(TRIM(documento)) REGEXP '^VTA[ _-]?[0-9]{1,15}$' GROUP BY empresa_id) h;
SELECT 'maximo historico CAN por empresa (empresa:valor)' AS verificacion, COALESCE(GROUP_CONCAT(CONCAT(empresa_id, ':', maximo) ORDER BY empresa_id SEPARATOR ', '), 'ninguno') AS resultado FROM (SELECT empresa_id, MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(codigo)), '^CAN[ _-]?', '') AS UNSIGNED)) AS maximo FROM `u611730801_Plataforma`.canecas_productos WHERE UPPER(TRIM(codigo)) REGEXP '^CAN[ _-]?[0-9]{1,15}$' GROUP BY empresa_id) h;
SELECT 'documentos historicos con formato distinto de PREFIJO-######' AS verificacion, CAST((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_compras WHERE UPPER(TRIM(referencia)) REGEXP '^COMP[ _-]?[0-9]{1,15}$' AND NOT (referencia REGEXP '^COMP-[0-9]{6}$')) + (SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_ventas WHERE UPPER(TRIM(documento)) REGEXP '^VTA[ _-]?[0-9]{1,15}$' AND NOT (documento REGEXP '^VTA-[0-9]{6}$')) + (SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_productos WHERE UPPER(TRIM(codigo)) REGEXP '^CAN[ _-]?[0-9]{1,15}$' AND NOT (codigo REGEXP '^CAN-[0-9]{6}$')) AS CHAR) AS resultado;
SELECT 'sin referencias COMP-###### duplicadas dentro de una empresa' AS verificacion, IF((SELECT COUNT(*) FROM (SELECT empresa_id FROM `u611730801_Plataforma`.canecas_compras WHERE referencia REGEXP '^COMP-[0-9]{6,15}$' GROUP BY empresa_id, referencia HAVING COUNT(*)>1) t)=0, 'OK', 'DETENER') AS resultado;
SELECT 'sin documentos VTA-###### duplicados dentro de una empresa' AS verificacion, IF((SELECT COUNT(*) FROM (SELECT empresa_id FROM `u611730801_Plataforma`.canecas_ventas WHERE documento REGEXP '^VTA-[0-9]{6,15}$' GROUP BY empresa_id, documento HAVING COUNT(*)>1) t)=0, 'OK', 'DETENER') AS resultado;
SELECT 'recuento canecas_ventas' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_ventas;
SELECT 'recuento canecas_productos' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_productos;
